const icons={heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',chevron:'<path d="m9 5 7 7-7 7"/>',down:'<path d="m6 9 6 6 6-6"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M16 3v4M8 3v4M3 11h18m-13 4h2m4 0h2m-8 3h2"/>',coffee:'<path d="M4 8h13v8a4 4 0 0 1-4 4H8a4 4 0 0 1-4-4V8Zm13 1h2a3 3 0 1 1 0 6h-2M7 2v3m5-3v3M2 22h18"/>',shield:'<path d="m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6l9-4Z"/><path d="m8 12 3 3 5-6"/>',users:'<circle cx="9" cy="7" r="4"/><path d="M2 21v-3a7 7 0 0 1 14 0v3m0-18a4 4 0 0 1 0 8m3 3a7 7 0 0 1 3 7"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',spark:'<path d="m12 3 2.4 6.6L21 12l-6.6 2.4L12 21l-2.4-6.6L3 12l6.6-2.4L12 3Zm8-1v4m-2-2h4"/>',check:'<path d="m5 12 4 4L19 6"/>',film:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M7 3v18M17 3v18M3 8h4m-4 8h4m10-8h4m-4 8h4"/>',food:'<path d="M4 2v7a3 3 0 0 0 6 0V2M7 2v20M20 22V2c-5 1-5 10 0 11"/>',compass:'<circle cx="12" cy="12" r="10"/><path d="m16 8-2 6-6 2 2-6 6-2Z"/>',music:'<path d="M9 18V5l12-3v13M9 9l12-3"/><ellipse cx="6" cy="18" rx="3" ry="3"/><ellipse cx="18" cy="15" rx="3" ry="3"/>',message:'<path d="M21 11.5a9 9 0 0 1-9.5 9A10 10 0 0 1 7 19.4L2 21l1.6-5a10 10 0 0 1-1.1-4.5A9 9 0 0 1 12 2a9 9 0 0 1 9 9.5Z"/>',search:'<circle cx="10.5" cy="10.5" r="7.5"/><path d="m16 16 6 6"/>',lock:'<rect x="4" y="10" width="16" height="12" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4m-4 5v3"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',clock:'<circle cx="12" cy="12" r="10"/><path d="M12 6v6l4 2"/>',mail:'<rect x="2" y="4" width="20" height="16" rx="2"/><path d="m2 6 10 7L22 6"/>',logout:'<path d="M9 21H4V3h5m5 4 5 5-5 5m-6-5h13"/>',info:'<circle cx="12" cy="12" r="10"/><path d="M12 11v6m0-11v1"/>'};
icons.bell='<path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/>';
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.spark}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const activities=[['coffee','Coffee & conversations','A little caffeine. A real connection.'],['food','Food & dining','Great food tastes better together.'],['film','Movies','Find your next movie buddy.'],['compass','City exploring','New streets. Shared discoveries.'],['music','Events & music','Make memories, not just plans.']];
let user=null,pricing={male_amount:29900},calDate=new Date(),selectedDate='',selectedSlot='',viewMode='month';
const root=document.getElementById('app');
const link=(path,text,cls='')=>`<a href="${path}" data-link class="${cls}">${text}</a>`;
const btn=(text,action,cls='btn btn-primary')=>`<button type="button" class="${cls}" data-action="${action}">${text}</button>`;
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Kolkata',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
async function api(path,options={}){const r=await fetch(path,{...options,headers:{'Content-Type':'application/json',...options.headers}});const data=await r.json();if(!r.ok)throw new Error(data.error||'Something went wrong. Please try again.');return data;}
function header(){return `<header class="site-header"><div class="container header-inner">${link('/',`<span class="logo-mark">${icon('heart')}</span>saathlumi<span class="logo-dot">.</span>`,'brand')}<nav class="desktop-nav" aria-label="Main navigation">${link('/browse','Make a private plan',location.pathname==='/browse'?'active':'')}${link('/how-it-works','How it works')}${link('/safety','Safety first')}${link('/pricing','Pricing')}</nav><div class="header-actions">${user?`${link('/notifications',icon('bell')+'<span class="sr-only">Notifications</span><span class="unread-badge" data-unread hidden></span>','icon-button notification-nav')}${link('/dashboard',icon('user')+' My space','login-link')}${btn(icon('logout')+'<span class="sr-only">Log out</span>','logout','icon-button')}`:`${link('/login','Log in','login-link')}${link('/register','Get started '+icon('arrow'),'btn btn-primary btn-small')}`}<button class="icon-button mobile-menu" data-action="menu" aria-label="Open navigation">${icon('menu')}</button></div></div><nav class="mobile-nav" hidden>${link('/browse','Make a private plan')}${link('/how-it-works','How it works')}${link('/safety','Safety first')}${link('/pricing','Pricing')}${link('/dashboard','My space')}</nav></header>`;}
function footer(){return `<footer class="site-footer"><div class="container footer-grid"><section>${link('/',`<span class="logo-mark">${icon('heart')}</span>saathlumi<span class="logo-dot">.</span>`,'brand')}<p>Because life is better<br>with a little good company.</p><span class="footer-age">18+ only · Platonic connections</span></section><section><h3>Explore</h3>${link('/browse','Make a private plan')}${link('/notifications','Get notified')}${link('/how-it-works','How it works')}${link('/pricing','Membership')}</section><section><h3>We’re here for you</h3>${link('/safety','Safety centre')}${link('/guidelines','Community guidelines')}${link('/contact','Contact & support')}${link('/#faq','FAQs')}</section><section><h3>The important things</h3>${link('/terms','Terms of service')}${link('/privacy','Privacy policy')}${link('/refunds','Cancellation & refunds')}<p class="footer-note">Built around respect.<br>Designed for real connection.</p></section></div><div class="container footer-bottom"><span>© ${new Date().getFullYear()} Saathlumi. All rights reserved.</span><span>Made for meaningful moments in India <span class="coral">${icon('heart')}</span></span></div></footer>`;}
function searchBar(){return `<form id="discovery-search" class="search-panel"><label><span>${icon('pin')} YOUR CITY</span><select name="city" aria-label="Your city"><option value="">Choose your city</option>${['Bengaluru','Mumbai','Delhi','Pune','Hyderabad'].map(c=>`<option>${c}</option>`).join('')}</select></label><label><span>${icon('coffee')} WHAT’S THE PLAN?</span><select name="activity" aria-label="Activity"><option value="">Pick an activity</option>${activities.map(a=>`<option>${a[1]}</option>`).join('')}</select></label><label><span>${icon('calendar')} WHEN?</span><input type="date" name="date" min="${today()}" aria-label="Meeting date"></label><button class="btn btn-primary" type="submit">${icon('search')} Make a private plan</button></form>`;}
function howSteps(){return `<div class="steps-grid">${[['lock','01','Keep it personal','Create a private account. No photos, searchable profiles, or public member lists.'],['calendar','02','Share a little plan','Pick a city, an activity, and a time. Your name stays hidden.'],['bell','03','A quiet notification','Matching, opted-in members receive a private in-app invitation.'],['heart','04','Only if you want to','Show interest or decline. Neither choice reveals your identity or confirms a meeting.']].map(v=>`<article class="step"><div class="step-icon">${icon(v[0])}<span>${v[1]}</span></div><h3>${v[2]}</h3><p>${v[3]}</p></article>`).join('')}</div>`;}
function pricingCards(){return `<div class="pricing-grid"><article class="price-card"><span class="eyebrow">YOUR FIRST HELLO</span><h3>A new connection.<br>Starts with you.</h3><div class="price">Join<span>Create your account to get started</span></div><ul class="check-list"><li>${icon('check')} Create your own profile</li><li>${icon('check')} Choose your private meeting interests</li><li>${icon('check')} View your membership details after login</li></ul>${link('/register','Create an account '+icon('arrow'),'btn btn-outline')}</article><article class="price-card featured-price"><span class="price-ribbon">ONE PAYMENT. MORE POSSIBILITIES.</span><span class="eyebrow">FOR MEN</span><h3>Good company.<br>One simple membership.</h3><div class="price">₹${pricing.male_amount/100}<span>One time. No subscriptions.</span></div><ul class="check-list"><li>${icon('check')} Private plans & in-app invitations</li><li>${icon('check')} Unlock booking requests & messaging</li><li>${icon('check')} No automatic renewals. No surprises.</li></ul>${link(user?'/checkout':'/register?gender=man','Get started '+icon('arrow'),'btn btn-primary')}</article></div><p class="pricing-disclaimer">Membership is for platform access, not a meeting fee. No companion charges are configured.<br>Plans require mutual acceptance. Personal activity expenses are separate.</p>`;}
function faq(){const items=[['Will anyone see my photo or profile?','No. There are no photos or public member profiles. Invitations only show the city, activity, and proposed time—not names or contact details.'],['How will I know someone wants to meet?','Opt in to a city and activities in Notifications. Eligible matching plans create in-app invitations. If you show interest, the plan’s sender receives a private reply notification. You can decline or block without disclosing your identity. Email and push alerts are not enabled.'],['What is Saathlumi, exactly?','Saathlumi is an adults-only platform for finding company for platonic activities—coffee, a movie, a meal, or exploring your city. It is not a dating guarantee or a sexual-services platform.'],['Is this a dating or escort service?','No. All connections are strictly platonic. Sexual services, coercion, harassment, and trafficking are prohibited. Everyone’s boundaries and consent must be respected.'],['What does the ₹299 membership include?','The ₹299 one-time paid membership is intended to unlock booking requests and permitted messaging. Your applicable membership details are shown after login and before any payment. It is not a per-meeting charge, and payment never guarantees an accepted request. Payments are disabled in this preview.'],['How do I stay safe when meeting someone?','Meet in a busy public place, tell someone you trust about your plan, keep contact details private until comfortable, and leave whenever you wish. Report concerning behavior through the safety centre.'],['Can I cancel a plan?','Yes. Either person can withdraw consent or cancel. Let the other person know as early as possible. Cancellation rules and membership refunds are separate; review the draft Cancellation & Refund Policy.']];return `<div class="faq-list">${items.map(([q,a])=>`<details><summary>${q}<span>+</span></summary><p>${a}</p></details>`).join('')}</div>`;}
function home(){return `<main><section class="hero-section"><div class="container hero-grid"><div class="hero-copy"><span class="eyebrow hero-eyebrow">${icon('spark')} A LITTLE COMPANY. A LOT MORE PRIVACY.</span><h1>Good company.<br><em>Meaningful</em><br>moments.</h1><p>You don’t need a public profile to make a connection. Share a private plan for coffee, conversation, or a day out. When someone is interested, we’ll let you know in your account.</p><div class="hero-actions">${link('/browse','Make a private plan '+icon('arrow'),'btn btn-primary')}${link('/notifications','Get notified','btn btn-outline')}</div><div class="hero-assurances"><span>${icon('lock')} No photos. No public profiles.</span><span>${icon('heart')} Always your choice</span></div></div><div class="private-hero-art"><span class="privacy-orbit orbit-one"></span><span class="privacy-orbit orbit-two"></span><div class="private-seal">${icon('lock')} PRIVATE BY DESIGN</div><div class="invitation-illustration"><div class="illustration-top"><span class="notification-symbol">${icon('bell')}</span><span>SAATHLUMI<span class="illustration-label">How an invitation looks</span></span>${icon('lock')}</div><h2>Someone would<br>like to meet.</h2><p>A shared interest.<br>A possibility. No pressure.</p><div class="illustration-activity">${icon('coffee')} A coffee & a conversation</div><div class="illustration-choice"><span>Only if you’re interested ${icon('arrow')}</span></div></div><div class="privacy-footnote">${icon('shield')} Your identity stays with you.</div><span class="private-art-spark">${icon('spark')}</span></div></div><div class="container search-container">${searchBar()}</div></section><div class="values-strip"><div class="container">${[['lock','No public profiles'],['users','Adults 18+ only'],['heart','Strictly platonic'],['bell','Private in-app invitations']].map(v=>`<span>${icon(v[0])}${v[1]}</span>`).join('')}</div></div><section class="section container" id="how-it-works"><div class="section-heading centered"><span class="eyebrow">CONNECTION WITHOUT THE SPOTLIGHT</span><h2>A little hello. Kept between us.</h2><p>No browsing faces. Just shared interests and a choice.</p></div>${howSteps()}</section><section class="discover-section"><div class="container"><div class="section-heading heading-row"><div><span class="eyebrow">SOME THINGS SHOULD STAY PERSONAL</span><h2>Not a gallery. A possibility.</h2><p>You’ll hear about a matching plan—not see a list of people.</p></div>${link('/notifications','My notification preferences '+icon('arrow'),'text-link')}</div><div class="privacy-feature-grid">${[['lock','Your name stays private','No photos, names, contact details, or member counts appear in invitations.'],['bell','A notification, not a spotlight','In-app alerts go only to eligible members who opted in to that city and activity.'],['heart','Interest is never an obligation','Ignore, decline, or show interest. Nothing automatically becomes a booking.']].map(v=>`<article class="privacy-feature"><span>${icon(v[0])}</span><h3>${v[1]}</h3><p>${v[2]}</p></article>`).join('')}</div></div></section><section class="section container activities-section"><div class="section-heading centered"><span class="eyebrow">BIG MEMORIES. LITTLE PLANS.</span><h2>What are you in the mood for?</h2><p>Start with an activity. Keep the rest personal.</p></div><div class="activities-grid">${activities.map(a=>link('/browse?activity='+encodeURIComponent(a[1]),`<span class="activity-icon">${icon(a[0])}</span><h3>${a[1]}</h3><p>${a[2]}</p><span class="activity-arrow">${icon('arrow')}</span>`,'activity-card')).join('')}</div><p class="city-line">Planned launch cities <span>·</span> Bengaluru <span>·</span> Mumbai <span>·</span> Delhi <span>·</span> Pune <span>·</span> Hyderabad</p></section><section class="safety-section container"><div class="privacy-promise"><span class="shield-large">${icon('shield')}</span><span class="eyebrow">YOUR SPACE. YOUR CHOICE.</span><h2>Less exposure.<br>More peace of mind.</h2><p>No photos.<br>No public member directory.<br>No automatic identity sharing.</p></div><div class="safety-copy"><span class="eyebrow">YOUR COMFORT IS NON-NEGOTIABLE</span><h2>Good company starts<br>with feeling comfortable.</h2><p>Only a city, activity, and proposed time are shared with matching recipients. Your account details stay private. Participation always requires consent.</p><ul class="safety-list"><li>${icon('shield')} Clear community guidelines</li><li>${icon('heart')} No obligation to respond</li><li>${icon('lock')} Opt-in notifications you can pause</li></ul>${link('/safety','Explore our safety centre '+icon('arrow'),'text-link')}</div></section><section class="section container" id="pricing"><div class="section-heading centered"><span class="eyebrow">SIMPLE, JUST LIKE IT SHOULD BE</span><h2>A little investment in good company.</h2><p>Transparent membership. No subscriptions. No mixed signals.</p></div>${pricingCards()}</section><section class="faq-section container" id="faq"><div><span class="eyebrow">WONDERING ABOUT SOMETHING?</span><h2>A few good<br>questions.</h2><p>A little clarity before your first hello.</p>${link('/contact','Have another question? '+icon('arrow'),'text-link')}</div>${faq()}</section><section class="cta-section container"><div><span class="eyebrow">LET CONNECTION COME TO YOU</span><h2>Good company. Without the spotlight.</h2><p>Choose what you enjoy. We’ll keep your identity private.</p></div>${link('/notifications','Set my preferences '+icon('arrow'),'btn btn-primary')}</section></main>`;}
function browse(){const q=new URLSearchParams(location.search);return `<main class="container page-main"><div class="page-title"><span class="eyebrow">A PRIVATE PLAN. A SHARED POSSIBILITY.</span><h1>What would you like to do?</h1><p>No public profiles or photos. Only your city, activity, and proposed time are shared.</p></div><div class="private-plan-layout"><section class="panel"><span class="eyebrow">YOUR LITTLE PLAN</span><h2>Start with a moment.</h2><form id="private-plan-form"><div class="form-two"><label>City<select name="city" required><option value="">Choose a city</option>${['Bengaluru','Mumbai','Delhi','Pune','Hyderabad'].map(c=>`<option ${q.get('city')===c?'selected':''}>${c}</option>`).join('')}</select></label><label>Activity<select name="activity" required><option value="">Choose an activity</option>${activities.map(a=>`<option ${q.get('activity')===a[1]?'selected':''}>${a[1]}</option>`).join('')}</select></label></div><div class="form-two"><label>Date<input name="date" type="date" min="${today()}" value="${esc(q.get('date')||'')}" required></label><label>Time (IST)<input name="time" type="time" required></label></div><label>Duration<select name="duration"><option value="60">1 hour</option><option value="90">1.5 hours</option><option value="120">2 hours</option></select></label><label class="checkbox-label"><input name="consent" type="checkbox" required><span>I agree to share this plan’s city, activity and time with matching opted-in members. This is strictly platonic, and not a confirmed meeting.</span></label><div id="form-feedback" aria-live="polite"></div>${user?`<button class="btn btn-primary full" type="submit">Share my private interest ${icon('arrow')}</button>`:`<button class="btn btn-primary full" type="submit">Log in to share privately ${icon('arrow')}</button>`}<p class="form-note">No name, photo, exact location, or contact details will be included.</p></form></section><aside><section class="panel peach-panel"><span class="notification-symbol">${icon('bell')}</span><h2>A quiet notification.<br>A choice that’s yours.</h2><p>Matching members receive an in-app invitation. If someone responds with interest, you’ll get an in-app notification too.</p><ul class="check-list"><li>${icon('check')} Only opted-in, eligible members</li><li>${icon('check')} No matching member list or count</li><li>${icon('check')} No automatic identity sharing</li></ul>${link('/notifications','I’d like to get notified '+icon('arrow'),'text-link')}</section><div class="inline-notice">${icon('info')} Preview: sending requires email confirmation, adult verification, and active membership. Adult verification is not configured yet. No real matches are simulated. Email and push alerts are unavailable.</div></aside></div>${user?`<section class="panel"><h2>Your private interests</h2><div id="private-plans-list" aria-live="polite"><p>Loading your plans…</p></div></section>`:''}</main>`;}
function calendar(){const y=calDate.getFullYear(),m=calDate.getMonth(),days=new Date(y,m+1,0).getDate(),first=(new Date(y,m,1).getDay()+6)%7;let cells='';for(let i=0;i<first;i++)cells+='<span></span>';for(let d=1;d<=days;d++){const date=`${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;cells+=`<button type="button" class="day ${selectedDate===date?'selected':''} ${date===today()?'today':''}" data-date="${date}" ${date<today()?'disabled':''}>${d}</button>`;}return `<div class="calendar"><div class="calendar-heading"><strong>${calDate.toLocaleDateString('en-IN',{month:'long',year:'numeric'})}</strong><div><button type="button" class="icon-button" data-action="prev-month" aria-label="Previous month"><span class="flip">${icon('chevron')}</span></button><button type="button" class="icon-button" data-action="next-month" aria-label="Next month">${icon('chevron')}</button></div></div><div class="calendar-weekdays">${['M','T','W','T','F','S','S'].map(d=>`<span>${d}</span>`).join('')}</div><div class="calendar-days">${cells}</div>${selectedDate?`<div class="slot-heading">${esc(selectedDate)} · Possible times (IST)</div><div class="time-slots">${['10:00','12:00','14:00','16:00','18:00'].map(t=>`<button type="button" data-slot="${t}" class="time-slot ${selectedSlot===t?'selected':''}" ${new Date(selectedDate+'T'+t+':00+05:30').getTime()<Date.now()+3600000?'disabled':''}>${t}</button>`).join('')}</div>`:'<p class="calendar-hint">Pick a date to explore possible times</p>'}</div>`;}
function authPage(type){const isRegister=type==='register',reset=type==='reset-password',forgot=type==='forgot-password',verify=type==='verify-email';const q=new URLSearchParams(location.search);return `<main class="auth-page container"><section class="auth-story"><span class="eyebrow">A LITTLE GOOD COMPANY</span><h1>Every connection<br>starts with<br><em>a simple hello.</em></h1><p>A coffee, a new perspective, or just someone to share the day with. Find the moments that make life a little more meaningful.</p><div class="auth-private-note">${icon('lock')}<h3>A connection, not a public profile.</h3><p>No photos. No public listing. Your details stay private.</p></div><span class="story-note">Platonic. Respectful. Always your choice.</span></section><section class="auth-card"><span class="mini-brand">${icon('heart')}</span><h2>${isRegister?'Your next chapter starts here.':forgot?'Let’s get you back in.':reset?'A fresh start.':verify?'Verify your email.':'Good to see you again.'}</h2><p class="muted">${isRegister?'A few details. A world of good company.':forgot?'We’ll email you a secure password reset link.':reset?'Choose a strong, unique password.':verify?'Confirm your email using the link in your inbox.':'Log in to your little corner of Saathlumi.'}</p><div class="inline-notice">${icon('info')} Development preview — use test details and a password you don’t use elsewhere.</div><form id="auth-form" data-type="${type}">${isRegister?`<label>Your name<input name="name" autocomplete="name" required minlength="2" maxlength="60" placeholder="What should we call you?"></label>`:''}${!reset&&!verify?`<label>Email address<input name="email" type="email" autocomplete="email" placeholder="you@example.com" maxlength="254" required></label>`:''}${!forgot&&!verify?`<label>Password<div class="password-input"><input name="password" type="password" autocomplete="${isRegister||reset?'new-password':'current-password'}" minlength="${isRegister||reset?'12':'1'}" maxlength="128" required placeholder="${isRegister||reset?'At least 12 characters':'Your password'}"><button type="button" data-action="toggle-password" aria-label="Show password">Show</button></div></label>`:''}${isRegister?`<div class="form-two"><label>I identify as<select name="gender" required><option value="">Select</option><option value="woman" ${q.get('gender')==='woman'?'selected':''}>Woman</option><option value="man" ${q.get('gender')==='man'?'selected':''}>Man</option><option value="self-described">Self-described</option><option value="prefer-not-to-say">Prefer not to say</option></select></label><label>Date of birth<input name="dob" type="date" required max="${new Date(new Date().setFullYear(new Date().getFullYear()-18)).toISOString().slice(0,10)}"></label></div><label class="checkbox-label"><input name="companion" type="checkbox" ${q.get('role')==='companion'?'checked':''}> I’d also like to become a companion.</label><label class="checkbox-label"><input name="consent" type="checkbox" required> <span>I’m 18 or older and agree to the ${link('/terms','Terms')}, ${link('/privacy','Privacy Policy')}, and ${link('/guidelines','Community Guidelines')}.</span></label><div class="inline-notice">${icon('info')} Self-reported age is not identity verification. Adult verification is required before real meetings.</div>`:''}${type==='login'?`<div class="form-end">${link('/forgot-password','Forgot password?','text-link')}</div>`:''}<div id="form-feedback" aria-live="polite"></div><button class="btn btn-primary full" type="submit">${isRegister?'Create my account':forgot?'Send reset link':reset?'Update password':verify?'Verify email':'Log in'} ${icon('arrow')}</button>${verify?`<input type="hidden" name="token" value="${esc(q.get('token')||'')}">`:''}</form><p class="auth-switch">${isRegister?`Already a member? ${link('/login','Log in')}`:`New around here? ${link('/register','Create an account')}`}</p><p class="form-note">${icon('lock')} Your information stays private.<br>Email delivery requires provider configuration in this preview.</p></section></main>`;}
function dashboard(){if(!user)return gate('Your private corner of Saathlumi.','Log in to see your plans, membership, and private notifications.');return `<main class="container page-main"><div class="dashboard-heading"><div><span class="eyebrow">YOUR PRIVATE SPACE</span><h1>Hello, ${esc(user.name)}.</h1><p>No spotlight. Just the things that matter to you.</p></div>${link('/browse','Make a private plan '+icon('arrow'),'btn btn-primary')}</div><nav class="dashboard-tabs">${link('/dashboard','Overview','active')}${link('/notifications','Notifications')}${link('/calendar','My calendar')}${link('/onboarding','My details')}${link('/checkout','Membership')}</nav><div class="dashboard-stats"><article>${icon('lock')}<strong>Private</strong><span>No public profile or photos</span></article><article>${icon('bell')}<strong id="notification-count">—</strong><span>Unread in-app alerts</span></article><article>${icon('heart')}<strong>${user.membership==='active'?'Active':'Not active'}</strong><span>Membership</span></article></div>${!user.email_verified?`<div class="sample-notice">${icon('mail')} Please verify your email. Email delivery is ${user.email_delivery?'configured':'not configured yet'}. ${btn('Resend email','resend-email','text-link')}</div>`:''}<div class="dashboard-grid"><section class="panel"><div class="heading-row"><h2>Your private notifications</h2>${link('/notifications','View all '+icon('arrow'),'text-link')}</div><div id="notification-list" aria-live="polite"><p>Loading your notifications…</p></div></section><aside class="panel peach-panel"><span class="eyebrow">LET GOOD COMPANY FIND YOU</span><h2>Your interests.<br>Your invitation.</h2><p>Choose a city and the things you’d enjoy. Opt in to private notifications, and pause them whenever you wish.</p>${link('/notifications','Set my preferences '+icon('arrow'),'btn btn-outline')}<hr><p>${icon('shield')} Identity and contact details are never shared automatically.</p></aside></div><section class="panel"><h2>Your private interests</h2><div id="private-plans-list"><p>Loading your plans…</p></div></section><section class="panel account-actions"><h3>Your data, your choice</h3>${btn('Export my data','export-data','btn btn-outline')}${btn('Request account deletion','delete-account','text-link')}</section></main>`;}
function gate(title,text){return `<main class="container page-main"><section class="empty-state gate"><span class="empty-icon">${icon('lock')}</span><h1>${title}</h1><p>${text}</p><div class="hero-actions">${link('/login','Log in '+icon('arrow'),'btn btn-primary')}${link('/register','Create an account','btn btn-outline')}</div></section></main>`;}
function onboarding(){if(!user)return gate('Make yourself at home.','Create an account to set up your profile.');return `<main class="container page-main narrow-page"><span class="eyebrow">YOUR PROFILE, YOUR PERSONALITY</span><h1>A little more about you.</h1><p>Your account details are private. There is no public profile or member directory.</p><form id="profile-form" class="panel"><label>Display name<input name="display_name" value="${esc(user.name)}" required maxlength="60"></label><label>City<select name="city">${['Bengaluru','Mumbai','Delhi','Pune','Hyderabad'].map(c=>`<option>${c}</option>`).join('')}</select></label><label>Approximate area<input name="area" maxlength="80" placeholder="Neighbourhood only, not your address"></label><label>Your story<textarea name="bio" maxlength="1000" placeholder="What makes a good day for you?"></textarea></label><label>Languages<input name="languages" placeholder="English, Hindi" maxlength="150"></label><label>Interests<input name="interests" placeholder="Coffee, films, art" maxlength="250"></label><label>Your boundaries<textarea name="boundaries" maxlength="600" placeholder="Public places only, no personal contact details…"></textarea></label><label class="checkbox-label"><input type="checkbox" name="companion"> I want to offer platonic companionship.</label><div class="inline-notice">${icon('info')} Photos are not collected or displayed. Adult verification is not configured yet.</div><div id="form-feedback" aria-live="polite"></div><button class="btn btn-primary">Save my profile ${icon('check')}</button></form></main>`;}
function calendarPage(){return `<main class="container page-main"><div class="page-title"><span class="eyebrow">MAKE ROOM FOR GOOD COMPANY</span><h1>Your calendar.</h1><p>One good plan at a time. All times shown in Asia/Kolkata (IST).</p></div><div class="sample-notice">${icon('info')} Private calendar explorer · Selected dates are not bookings. Share a private interest to invite matching eligible members.</div><div class="calendar-page-grid"><section class="panel"><div class="view-switch">${['month','week','day'].map(v=>`<button data-view="${v}" class="${viewMode===v?'active':''}">${v[0].toUpperCase()+v.slice(1)}</button>`).join('')}</div><div id="calendar-widget">${calendar()}</div></section><section class="panel"><span class="eyebrow">A DAY WITH POSSIBILITIES</span><h2 id="calendar-selection">${selectedDate||'Choose your day.'}</h2><div id="agenda-detail" class="empty-state">${icon('calendar')}<h3>No confirmed bookings.</h3><p>Explore a date, then share a private interest. Confirmed meetings are not enabled yet.</p>${link('/browse','Make a private plan '+icon('arrow'),'text-link')}</div></section></div></main>`;}
function checkout(){return `<main class="container page-main narrow-page"><span class="eyebrow">ONE SIMPLE MEMBERSHIP</span><h1>More moments.<br>No subscriptions.</h1><section class="panel checkout-card"><h2>Saathlumi membership</h2><p>Unlock booking requests and permitted messaging.</p><div class="checkout-line"><span>One-time platform access</span><strong>${user?.gender==='woman'?'Free':'₹'+pricing.male_amount/100}</strong></div><div class="checkout-line"><span>Tax treatment</span><span>Awaiting business configuration</span></div><div class="checkout-line total"><span>${user?.gender==='woman'?'Membership':'Proposed total'}</span><strong>${user?.gender==='woman'?'Free':'₹'+pricing.male_amount/100}</strong></div><div class="inline-notice">${icon('lock')} Payments are disabled. Merchant approval, live credentials, tax configuration, and legal review are required before checkout opens.</div><button class="btn btn-primary full" disabled>Checkout not available yet ${icon('lock')}</button><p class="form-note">No payment has been taken. No automatic renewals.<br>Payment never guarantees an accepted booking.</p>${link('/refunds','Read the draft refund policy','text-link')}</section>${!user?link('/register','Create a free account first '+icon('arrow'),'text-link'):''}</main>`;}
const policies={terms:{title:'Terms of service',intro:'The foundation for respectful connections.',sections:[['Who can join','Saathlumi is intended only for adults aged 18 or older. All activities must be lawful, consensual, and strictly platonic. Self-declared age does not constitute verification.'],['Your membership','Membership eligibility and applicable charges are shown in your account before any payment. The proposed paid membership is ₹299 one time. Pricing policies require owner and legal review before launch. Membership is not a booking guarantee or payment for affection.'],['Bookings and boundaries','Every request requires the companion’s acceptance. Either person can withdraw consent. Meet in public and agree your plans clearly. No companion payouts or separate meeting fees are configured.'],['Preview limitations','There are no public profiles or photos. Private matching is gated by email confirmation, adult verification, and membership. Adult verification, payment collection, meeting confirmation, and staffed moderation are not operational.'],['Owner details','Legal entity, registered address, governing law, grievance officer, and support contact must be supplied and reviewed before public launch.']]},privacy:{title:'Your privacy matters.',intro:'A clearer picture of how your information is handled.',sections:[['Information collected','Account information includes email, name, declared date of birth, gender, password hash, policy consent, profile information, and session records. Profile and account data, notification preferences, private meeting interests, invitation responses, and in-app alerts are stored in Cloudflare D1 in this preview environment.'],['What is kept private','Passwords are hashed. Sessions use HttpOnly cookies. No profiles, photos, names, or contact details are published. Only a plan’s city, activity, and time are shared with its invited recipients. Private details remain accessible to you and authorized platform operators as needed; this is not end-to-end encryption.'],['Service providers','Cloudflare supports hosting and storage. Email and payment providers require owner configuration. Razorpay would process payment information; Saathlumi must not store raw card details.'],['Your choices','You can export your account information or request deletion from your dashboard. Deletion requests require operational follow-up. Retention periods and financial record exceptions must be finalized before launch.'],['External assets','Fonts are requested from Google Fonts. No photographic images are used. Configure final provider disclosures, lawful purposes, retention schedules, and grievance contacts before launch.']]},refunds:{title:'Plans change. That’s okay.',intro:'Cancellation and refund policy — draft for review.',sections:[['Meeting cancellations','Either person may cancel or withdraw consent at any time. Communicate as early as possible. This preview does not charge meeting cancellation fees.'],['Membership versus meetings','The proposed ₹299 is a one-time platform fee, not a meeting fee. A declined or cancelled meeting is not automatically the same as cancelling platform membership.'],['Payments are not live','No payments can be collected in this preview. Refund eligibility, processing periods, complaint contacts, and mandatory consumer rights must be settled before payments are enabled.'],['Refunded or disputed memberships','The planned integration revokes paid access after a full refund or an adverse payment dispute. Genuine disputes require manual review and a published appeals procedure.']]},guidelines:{title:'Good company. Shared values.',intro:'A community built on mutual respect.',sections:[['Adults only. No exceptions.','Participation by anyone under 18 is prohibited. Report any account you believe may belong to a minor.'],['Keep it platonic','No sexual services, trafficking, coercion, threats, or exploitation. Payment never entitles anyone to affection, physical contact, or continued participation.'],['Respect every no','Consent can be withdrawn at any moment. No repeated unwanted contact. Respect blocks, boundaries, privacy choices, and personal space.'],['Be honest and thoughtful','Use accurate profile information. Do not impersonate others, solicit money, share private information without permission, or publish misleading reviews.'],['Speak up safely','Use reporting and blocking controls when live member interactions are enabled. Moderation escalation and appeal procedures must be staffed before launch.']]}};
function policyPage(kind){const p=policies[kind];return `<main class="container page-main narrow-page"><span class="eyebrow">THE IMPORTANT THINGS</span><h1>${p.title}</h1><p class="lead">${p.intro}</p><div class="sample-notice">${icon('info')} Draft policy · Requires professional review and business details before launch.</div><article class="policy-body">${p.sections.map(([h,t])=>`<section><h2>${h}</h2><p>${t}</p></section>`).join('')}</article></main>`;}
function safety(){return `<main class="container page-main"><section class="safety-hero"><span class="shield-large">${icon('shield')}</span><span class="eyebrow">YOUR COMFORT COMES FIRST</span><h1>Real connection.<br>Real boundaries.</h1><p>You should never have to choose between meeting someone new and feeling comfortable. Your choices are always yours.</p></section><div class="safety-cards">${[['pin','Public place. Peace of mind.','Choose a busy café, gallery, or other public venue. Arrange your own transport and avoid sharing your home address.'],['users','Keep someone in the loop.','Tell a trusted person where you are going and when you expect to return. Check in with them after your meeting.'],['heart','A yes is never an obligation.','You can change your mind, cancel a plan, or leave. Membership never creates a right to another person’s time or attention.'],['lock','A little privacy goes a long way.','Keep conversations on the platform when available. Never send money or sensitive documents to another member.'],['shield','Notice something? Speak up.','Blocking and reporting must be available for real member interactions. Live moderation is not active in this preview.'],['message','Not an emergency service.','Saathlumi does not provide emergency monitoring. In immediate danger in India, contact emergency services on 112.']].map(v=>`<article class="panel">${icon(v[0])}<h2>${v[1]}</h2><p>${v[2]}</p></article>`).join('')}</div><div class="centered">${link('/guidelines','Read our community guidelines '+icon('arrow'),'btn btn-primary')}</div></main>`;}
function messages(){if(!user)return gate('A hello goes a long way.','Log in to see your conversations.');return `<main class="container page-main"><span class="eyebrow">A SPACE FOR CONVERSATION</span><h1>Your messages.</h1><section class="panel empty-state">${icon('message')}<h2>No conversations just yet.</h2><p>Conversations open after mutual booking acceptance, with active membership and verification.<br>Showing interest does not open a chat or reveal anyone’s identity. Meeting confirmation and mutual disclosure are not enabled yet.</p>${link('/browse','Make a private plan '+icon('arrow'),'btn btn-primary')}</section></main>`;}
function contact(){return `<main class="container page-main narrow-page"><span class="eyebrow">LET’S CLEAR THINGS UP</span><h1>A question?<br>We’re listening.</h1><p>Start with our FAQs and community guidelines.</p><div class="panel"><h2>Support is being set up.</h2><p>This preview does not have a staffed support inbox. A verified business email, response times, and grievance contact will be published before launch.</p><div class="inline-notice">${icon('info')} No message submission is available yet. Do not send sensitive information.</div>${link('/#faq','Browse common questions '+icon('arrow'),'btn btn-outline')}</div><div class="panel"><h2>Need urgent help?</h2><p>We are not an emergency service. If you’re in immediate danger in India, call <a href="tel:112">112</a>.</p></div></main>`;}
function howPage(){return `<main class="container page-main"><div class="page-title centered"><span class="eyebrow">LESS COMPLICATED. MORE HUMAN.</span><h1>A little hello.<br>A whole lot of possibility.</h1><p>Good company in four simple steps.</p></div>${howSteps()}<div class="panel how-bottom"><h2>Every good plan starts with mutual consent.</h2><p>Membership lets you request a meeting, not demand one. Choose public places, respect boundaries, and remember you can always change your mind.</p>${link('/browse','Explore the preview '+icon('arrow'),'btn btn-primary')}</div></main>`;}
function render(){const path=location.pathname;let body='';if(path==='/')body=home();else if(path==='/browse')body=browse();else if(path.startsWith('/companions/'))body=notFound();else if(['/register','/login','/forgot-password','/reset-password','/verify-email'].includes(path))body=authPage(path.slice(1));else if(path==='/pricing')body=`<main class="container page-main"><div class="page-title centered"><span class="eyebrow">GOOD COMPANY, CLEAR PRICING</span><h1>Simple membership.<br>No mixed signals.</h1><p>Free account creation for everyone. No recurring payments.</p></div>${pricingCards()}<div class="sample-notice pricing-review">${icon('info')} Before launch: gender-based pricing requires legal and provider review. Pricing for self-described and undisclosed genders is awaiting an owner decision. Taxes are not configured; checkout is disabled.</div></main>`;else if(path==='/dashboard')body=dashboard();else if(path==='/onboarding')body=onboarding();else if(path==='/calendar'||path==='/availability')body=calendarPage();else if(path==='/checkout'||path==='/payment-result')body=checkout();else if(path==='/messages')body=messages();else if(path==='/notifications')body=notificationsPage();else if(path==='/safety')body=safety();else if(path==='/contact')body=contact();else if(path==='/how-it-works')body=howPage();else if(policies[path.slice(1)])body=policyPage(path.slice(1));else if(path==='/admin')body=gate('Administration is protected.','Administrative access is disabled until MFA and administrator provisioning are configured.');else body=notFound();root.innerHTML=header()+body+footer();document.title=(path==='/'?'Good company. Meaningful moments.':path.split('/')[1].replaceAll('-',' ').replace(/^./,s=>s.toUpperCase()))+' | Saathlumi';if(path==='/browse'&&user)loadPrivatePlans();if(path==='/onboarding'&&user)loadProfile();if(path==='/dashboard'&&user){loadPrivatePlans();loadNotifications();}if(path==='/notifications'&&user){loadNotificationPreferences();loadNotifications();}if(user)refreshUnread();if(location.hash)setTimeout(()=>document.querySelector(location.hash)?.scrollIntoView({behavior:'smooth'}),80);}
function notificationsPage(){if(!user)return gate('A private invitation. Just for you.','Create an account or log in to choose your interests and receive private in-app notifications. No public profiles or photos.');return `<main class="container page-main"><div class="dashboard-heading"><div><span class="eyebrow">ONLY YOU CAN SEE YOUR INBOX</span><h1>A little hello.</h1><p>When someone wants to meet, you’ll hear about it here. No identity is shared automatically.</p></div>${btn('Refresh '+icon('arrow'),'refresh-notifications','btn btn-outline')}</div><div class="private-plan-layout"><section class="panel"><div class="heading-row"><h2>Your notifications</h2><span class="inbox-label">In-app only</span></div><div id="notification-list" aria-live="polite"><p>Loading your notifications…</p></div></section><aside class="panel"><span class="eyebrow">YOUR CHOICE TO OPT IN</span><h2>Let me know when…</h2><form id="notification-preferences-form"><label>Someone wants to meet in<select name="city" required><option value="">Choose a city</option>${['Bengaluru','Mumbai','Delhi','Pune','Hyderabad'].map(c=>`<option>${c}</option>`).join('')}</select></label><fieldset class="preference-activities"><legend>For an activity I enjoy</legend>${activities.map(a=>`<label class="checkbox-label"><input type="checkbox" name="activities" value="${a[1]}"> ${icon(a[0])}<span>${a[1]}</span></label>`).join('')}</fieldset><label class="checkbox-label opt-in-label"><input type="checkbox" name="enabled"><span>I want private in-app invitations for these interests. I can pause new invitations by unticking this box and saving.</span></label><div class="inline-notice">${icon('lock')} Preferences are saved privately. Matching requires email confirmation, adult verification, and active membership. Saving preferences alone does not make you eligible.</div><div id="form-feedback" aria-live="polite"></div><button class="btn btn-primary full" type="submit">Save my preferences ${icon('check')}</button></form><p class="form-note">Email and push alerts are not enabled. Check this inbox while logged in. It refreshes every 30 seconds while open.</p></aside></div></main>`;}
function meetingTime(timestamp){return new Intl.DateTimeFormat('en-IN',{timeZone:'Asia/Kolkata',dateStyle:'medium',timeStyle:'short'}).format(new Date(timestamp*1000))+' IST';}
function notificationMarkup(n){const inv=n.invitation;return `<article class="private-notification ${n.read_at?'':'unread'}"><div class="notification-heading"><span class="notification-symbol">${icon(n.kind==='private_reply'?'heart':'bell')}</span><h3>${n.kind==='private_reply'?'Someone is interested.':'Someone would like to meet.'}</h3>${!n.read_at?'<span class="unread-dot" aria-label="Unread"></span>':''}</div><p>${esc(n.body)}</p>${inv?`<dl class="notification-details"><dt>Plan</dt><dd>${esc(inv.activity)}</dd><dt>City</dt><dd>${esc(inv.city)}</dd><dt>When</dt><dd>${esc(meetingTime(inv.start_at))}</dd><dt>Duration</dt><dd>${(inv.end_at-inv.start_at)/60} minutes</dd></dl><p class="private-reminder">${icon('lock')} Names, photos, and contact details stay private.</p>${inv.role==='recipient'&&inv.state==='pending'?`<div class="notification-actions"><button class="btn btn-primary btn-small" data-response="interested" data-invitation="${esc(inv.id)}">I’m interested</button><button class="btn btn-outline btn-small" data-response="declined" data-invitation="${esc(inv.id)}">Not this time</button></div>`:`<p class="response-status">${inv.state==='declined'?'You declined this invitation.':'Interest shared privately. Meeting confirmation is not yet enabled.'}</p>`}<div class="notification-secondary"><button class="text-link" data-private-block="${esc(inv.id)}">Block this member</button>${!n.read_at?`<button class="text-link" data-read-notification="${esc(n.id)}">Mark as read</button>`:''}</div>`:''}</article>`;}
function updateUnread(count){document.querySelectorAll('[data-unread]').forEach(el=>{el.textContent=String(count);el.hidden=count===0;});const number=document.getElementById('notification-count');if(number)number.textContent=String(count);}
async function loadNotifications(quiet=false){const uid=user?.id;if(!uid)return;try{const data=await api('/api/notifications');if(user?.id!==uid)return;updateUnread(data.unread);const list=document.getElementById('notification-list');if(list)list.innerHTML=data.notifications.length?data.notifications.map(notificationMarkup).join(''):`<div class="empty-state">${icon('bell')}<h3>We’ll keep you in the loop.</h3><p>No private invitations yet. Choose your interests and opt in. You’ll see an alert here when an eligible matching plan arrives.</p><p class="form-note">No members or matches are simulated in this preview.</p></div>`;}catch(err){if(!quiet){const list=document.getElementById('notification-list');if(list)list.innerHTML=`<p class="form-error">${esc(err.message)}</p>`;}}}
async function refreshUnread(){if(document.getElementById('notification-list'))return;const uid=user?.id;if(!uid)return;try{const data=await api('/api/notifications');if(user?.id===uid)updateUnread(data.unread);}catch{}}
async function loadNotificationPreferences(){const uid=user?.id;try{const {preferences:p}=await api('/api/notification-preferences');if(user?.id!==uid)return;const f=document.getElementById('notification-preferences-form');if(!f||f.contains(document.activeElement))return;f.elements.city.value=p.city;f.elements.enabled.checked=p.enabled;f.querySelectorAll('[name=activities]').forEach(input=>input.checked=p.activities.includes(input.value));}catch(err){feedback(err.message,true);}}
async function loadPrivatePlans(){const uid=user?.id;if(!uid)return;try{const {plans}=await api('/api/private-plans');if(user?.id!==uid)return;const list=document.getElementById('private-plans-list');if(!list)return;list.innerHTML=plans.length?plans.map(p=>`<article class="own-private-plan"><div><h3>${esc(p.activity)}</h3><p>${esc(p.city)} · ${esc(meetingTime(p.start_at))}</p><span class="plan-state">${p.status==='open'?'Private interest open':esc(p.status)}</span></div>${p.status==='open'?`<button class="text-link" data-cancel-plan="${esc(p.id)}">Cancel interest</button>`:''}</article>`).join(''):'<div class="empty-state"><h3>Your next moment starts here.</h3><p>No private interests shared yet. Only you can see this list.</p>'+link('/browse','Make a private plan '+icon('arrow'),'text-link')+'</div>';}catch(err){const list=document.getElementById('private-plans-list');if(list)list.innerHTML=`<p class="form-error">${esc(err.message)}</p>`;}}
document.addEventListener('click',async e=>{const response=e.target.closest('[data-response]'),read=e.target.closest('[data-read-notification]'),cancel=e.target.closest('[data-cancel-plan]'),block=e.target.closest('[data-private-block]'),confirm=e.target.closest('[data-confirm-private]');try{if(response){response.disabled=true;const result=await api('/api/private-invitations/'+encodeURIComponent(response.dataset.invitation)+'/respond',{method:'POST',body:JSON.stringify({response:response.dataset.response})});toast(result.message);await loadNotifications();}if(read){read.disabled=true;await api('/api/notifications/'+encodeURIComponent(read.dataset.readNotification)+'/read',{method:'POST'});await loadNotifications();}if(cancel)modal('Cancel this private interest?',`<p>Matching recipients will no longer see or respond to this plan. Your identity remains private.</p><button class="btn btn-primary" data-confirm-private="cancel" data-target="${esc(cancel.dataset.cancelPlan)}">Cancel interest</button>`);if(block)modal('Keep your boundaries.',`<p>Block this member and hide your shared invitations from each other? Their identity is not disclosed.</p><button class="btn btn-primary" data-confirm-private="block" data-target="${esc(block.dataset.privateBlock)}">Block member</button>`);if(confirm){confirm.disabled=true;const path=confirm.dataset.confirmPrivate==='cancel'?'/api/private-plans/'+encodeURIComponent(confirm.dataset.target)+'/cancel':'/api/private-invitations/'+encodeURIComponent(confirm.dataset.target)+'/block';await api(path,{method:'POST'});document.getElementById('app-dialog').close();await loadPrivatePlans();await loadNotifications();toast(confirm.dataset.confirmPrivate==='cancel'?'Private interest cancelled.':'Member blocked.');}if(e.target.closest('[data-action="refresh-notifications"]'))await loadNotifications();}catch(err){toast(err.message);}finally{if(response?.isConnected)response.disabled=false;if(read?.isConnected)read.disabled=false;if(confirm?.isConnected)confirm.disabled=false;}});
setInterval(()=>{if(user&&!document.hidden){if(document.getElementById('notification-list'))loadNotifications(true);else refreshUnread();}},30000);
function notFound(){return `<main class="container page-main empty-state"><span class="eyebrow">404 · A LITTLE OFF THE PATH</span><h1>This isn’t the moment<br>you were looking for.</h1><p>Let’s get you back to some good company.</p>${link('/','Back home '+icon('arrow'),'btn btn-primary')}</main>`;}
function navigate(path){history.pushState({},'',path);selectedDate='';selectedSlot='';render();window.scrollTo(0,0);}
function toast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('visible'),5000);}
function modal(title,content){const d=document.getElementById('app-dialog');d.innerHTML=`<button class="dialog-close icon-button" data-action="close-modal" aria-label="Close dialog">${icon('close')}</button><span class="mini-brand">${icon('calendar')}</span><h2>${title}</h2>${content}`;d.showModal();}
function feedback(text,error=false){const el=document.getElementById('form-feedback');if(el){el.className=error?'form-error':'form-success';el.textContent=text;}}
function refreshCalendar(){const el=document.getElementById('calendar-widget');if(el)el.innerHTML=calendar();const label=document.getElementById('calendar-selection');if(label)label.textContent=selectedDate||'Choose your day.';applyCalendarView();}
function applyCalendarView(){const days=document.querySelector('.calendar-days');if(!days||location.pathname!='/calendar'&&location.pathname!='/availability')return;if(viewMode!=='month'){const current=selectedDate||today();const day=new Date(current+'T12:00:00'),weekday=(day.getDay()+6)%7;const start=new Date(day);start.setDate(day.getDate()-weekday);const end=new Date(start);end.setDate(start.getDate()+6);days.querySelectorAll('[data-date]').forEach(b=>{const d=new Date(b.dataset.date+'T12:00:00');b.hidden=viewMode==='day'?b.dataset.date!==current:d<start||d>end;});days.querySelectorAll('span').forEach(s=>s.hidden=true);} }
document.addEventListener('click',async e=>{const a=e.target.closest('a[data-link]');if(a){if(e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;e.preventDefault();navigate(a.getAttribute('href'));return;}const d=e.target.closest('[data-date]');if(d){selectedDate=d.dataset.date;selectedSlot='';refreshCalendar();return;}const s=e.target.closest('[data-slot]');if(s){selectedSlot=s.dataset.slot;refreshCalendar();return;}const v=e.target.closest('[data-view]');if(v){viewMode=v.dataset.view;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b===v));refreshCalendar();return;}const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;if(action==='menu'){const n=document.querySelector('.mobile-nav');n.hidden=!n.hidden;}if(action==='toggle-password'){const input=b.previousElementSibling;input.type=input.type==='password'?'text':'password';b.textContent=input.type==='password'?'Show':'Hide';}if(action==='prev-month'||action==='next-month'){calDate=new Date(calDate.getFullYear(),calDate.getMonth()+(action==='next-month'?1:-1),1);refreshCalendar();}if(action==='close-modal')document.getElementById('app-dialog').close();if(action==='logout'){try{await api('/api/auth/logout',{method:'POST'});user=null;navigate('/');toast('You’ve been logged out. See you soon.');}catch(err){toast(err.message);}}if(action==='resend-email'){try{const r=await api('/api/auth/resend',{method:'POST'});toast(r.message);}catch(err){toast(err.message);}}if(action==='export-data'){try{const data=await api('/api/account/export');const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='saathlumi-my-data.json';a.click();URL.revokeObjectURL(url);}catch(err){toast(err.message);}}if(action==='delete-account'){modal('Your data, your choice.',`<p>Submit an account deletion request? Your profile will be hidden immediately. Actual deletion and any financial retention exceptions require an operator’s review; no processing deadline is promised in this preview.</p>${btn('Submit deletion request','confirm-delete','btn btn-primary')}`);}if(action==='confirm-delete'){try{await api('/api/account/deletion',{method:'POST'});document.getElementById('app-dialog').close();toast('Deletion request recorded. Your profile is hidden pending review.');}catch(err){toast(err.message);}}});
document.addEventListener('submit',async e=>{const f=e.target;if(!(f instanceof HTMLFormElement))return;e.preventDefault();const v=Object.fromEntries(new FormData(f));if(f.id==='discovery-search'){navigate('/browse?'+new URLSearchParams(v));return;}const submit=f.querySelector('[type="submit"],button:not([type])');if(submit)submit.disabled=true;try{if(f.id==='private-plan-form'){if(!user){navigate('/login');toast('Please log in to share your plan.');return;}const start=Math.floor(new Date(v.date+'T'+v.time+':00+05:30').getTime()/1000);const r=await api('/api/private-plans',{method:'POST',body:JSON.stringify({city:v.city,activity:v.activity,start_at:start,end_at:start+Number(v.duration)*60,consent:v.consent==='on'})});feedback(r.message);loadPrivatePlans();}if(f.id==='notification-preferences-form'){const r=await api('/api/notification-preferences',{method:'PUT',body:JSON.stringify({city:v.city,activities:new FormData(f).getAll('activities'),enabled:v.enabled==='on',consent:v.enabled==='on'})});feedback(r.message);}if(f.id==='auth-form'){const type=f.dataset.type;if(type==='register'){const r=await api('/api/auth/register',{method:'POST',body:JSON.stringify({...v,consent:v.consent==='on',companion:v.companion==='on'})});user=r.user;navigate('/dashboard');toast(r.message);}else if(type==='login'){const r=await api('/api/auth/login',{method:'POST',body:JSON.stringify(v)});user=r.user;navigate('/dashboard');}else if(type==='forgot-password'){const r=await api('/api/auth/forgot',{method:'POST',body:JSON.stringify(v)});feedback(r.message);}else if(type==='reset-password'){await api('/api/auth/reset',{method:'POST',body:JSON.stringify({...v,token:new URLSearchParams(location.search).get('token')})});navigate('/login');toast('Password updated. Please log in again.');}else if(type==='verify-email'){await api('/api/auth/verify',{method:'POST',body:JSON.stringify(v)});const me=await api('/api/auth/me');user=me.user;navigate('/dashboard');toast('Email confirmed. Thank you!');}}if(f.id==='profile-form'){await api('/api/profile',{method:'PUT',body:JSON.stringify({...v,companion:v.companion==='on'})});feedback('Your details are saved privately. They are never added to a public member directory.');}}catch(err){feedback(err.message,true);}finally{if(submit)submit.disabled=false;}});
async function loadProfile(){try{const data=await api('/api/profile');if(!data.profile)return;const f=document.getElementById('profile-form');if(!f)return;for(const [k,v]of Object.entries(data.profile)){const input=f.elements.namedItem(k);if(input&&input.type!=='checkbox')input.value=v||'';}f.elements.companion.checked=!!data.profile.companion;}catch(err){toast(err.message);}}

window.addEventListener('popstate',render);document.getElementById('app-dialog').addEventListener('click',e=>{if(e.target.tagName==='DIALOG')e.target.close();});document.addEventListener('click',e=>{if(e.target.closest('#app-dialog a[data-link]'))document.getElementById('app-dialog').close();});
render();Promise.all([api('/api/auth/me').then(d=>user=d.user),api('/api/config').then(d=>pricing=d.pricing)]).then(()=>{if(!document.querySelector('input:focus,textarea:focus,select:focus'))render();}).catch(()=>{});
